    real_t x0 = 0.0, h = 1.0 / (real_t)LEN_1D;
    real_t yp = 1.0, ypoint = 1.0;
    real_t acc = 0.0;

    // Use RISC-V Vector intrinsics to optimize the loop
    __rvv_float32m1_t xv_vec, denom_vec, sumx_vec;
    __rvv_float32m1_t xv_vec_init = __rvv_float32m1_splat(x0);
    __rvv_float32m1_t h_vec = __rvv_float32m1_splat(h);
    __rvv_float32m1_t yp_vec = __rvv_float32m1_splat(yp);
    __rvv_float32m1_t ypoint_vec = __rvv_float32m1_splat(ypoint);
    __rvv_float32m1_t acc_vec = __rvv_float32m1_splat(acc);

    for (int nl = 0; nl < iterations; nl++) {
        // Initialize the vector variables
        xv_vec = xv_vec_init;
        denom_vec = __rvv_float32m1_splat(0.0);
        sumx_vec = __rvv_float32m1_splat(0.0);

        // Perform the loop body using RISC-V Vector intrinsics
        for (Index_type i = 0; i < LEN_1D; i += __rvv_float32m1_t::size()) {
            // Load the vector variables
            xv_vec = __rvv_float32m1_load(xv_vec_init + i);
            denom_vec = __rvv_float32m1_load(denom_vec + i);
            sumx_vec = __rvv_float32m1_load(sumx_vec + i);

            // Perform the computation using RISC-V Vector intrinsics
            xv_vec = __rvv_float32m1_add(xv_vec, __rvv_float32m1_mul(h_vec, __rvv_float32m1_splat(i)));
            denom_vec = __rvv_float32m1_add(denom_vec, __rvv_float32m1_mul(xv_vec, xv_vec));
            denom_vec = __rvv_float32m1_add(denom_vec, __rvv_float32m1_mul(ypoint_vec, ypoint_vec));
            sumx_vec = __rvv_float32m1_add(sumx_vec, __rvv_float32m1_div(1.0f, __rvv_float32m1_sqrt(denom_vec + 1.0f)));

            // Store the vector variables
            __rvv_float32m1_store(xv_vec, xv_vec_init + i);
            __rvv_float32m1_store(denom_vec, denom_vec + i);
            __rvv_float32m1_store(sumx_vec, sumx_vec + i);
        }

        // Accumulate the results
        acc_vec = __rvv_float32m1_add(acc_vec, sumx_vec);
    }

    // Store the final result
    x[0] = __rvv_float32m1_extract(acc_vec, 0);

    gettimeofday(&func_args->t2, NULL);
    return calc_checksum(__func__);
}

