                __rvv_float32m1_t za_mul = __rvv_vmul_vv_f32m1(za, zu, RVV_M);
                __rvv_float32m1_t zb_mul = __rvv_vmul_vv_f32m1(zb, zv, RVV_M);
                __rvv_float32m1_t zu_add = __rvv_vadd_vv_f32m1(za_mul, zb_mul, RVV_M);
                __rvv_float32m1_t zv_add = __rvv_vadd_vv_f32m1(za_mul, zb_mul, RVV_M);

                // Store the results in the output arrays
                zrout[k][j] = __rvv_vfloat32m1_t(zr[k][j] + t*zu_add);
                zzout[k][j] = __rvv_vfloat32m1_t(zz[k][j] + t*zv_add);
